// Prepara el resumen de la mañana para Katherine
const filas = $input.all().map(i => i.json);
const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
const DIA = 86400000;

function fecha(texto) {
  const m = String(texto || '').match(/(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (!m) return null;
  const anio = m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]);
  return new Date(anio, Number(m[2]) - 1, Number(m[1]));
}
const estado = f => String(f['Estado'] || '').trim().toLowerCase();
const fila = f => `<tr><td style="padding:6px 8px">${f['ID'] || ''}</td><td style="padding:6px 8px">${f['Cliente'] || ''}</td>` +
  `<td style="padding:6px 8px">${f['Tipo de evento'] || ''}</td><td style="padding:6px 8px">${f['Fecha evento'] || ''}</td>` +
  `<td style="padding:6px 8px">${f['Lugar'] || ''}</td><td style="padding:6px 8px">${f['Paquete'] || ''}</td>` +
  `<td style="padding:6px 8px">${f['WhatsApp'] ? `<a href="${f['WhatsApp']}">WhatsApp</a>` : (f['Teléfono'] || '')}</td></tr>`;
const tabla = lista => `<table style="border-collapse:collapse;font-size:14px;width:100%">` +
  `<tr style="background:#fdf1f3;text-align:left"><th style="padding:6px 8px">ID</th><th style="padding:6px 8px">Cliente</th><th style="padding:6px 8px">Evento</th><th style="padding:6px 8px">Fecha</th><th style="padding:6px 8px">Lugar</th><th style="padding:6px 8px">Paquete</th><th style="padding:6px 8px">Contacto</th></tr>` +
  lista.map(fila).join('') + `</table>`;

// 1) Solicitudes sin responder
const sinResponder = filas.filter(f => estado(f) === 'nuevo');
// 2) Eventos reservados en los próximos 7 días
const proximos = filas.filter(f => {
  const d = fecha(f['Fecha evento']);
  return estado(f) === 'reservado' && d && d >= hoy && (d - hoy) / DIA <= 7;
}).sort((a, b) => fecha(a['Fecha evento']) - fecha(b['Fecha evento']));
// 3) Presupuestos enviados hace días sin respuesta (para hacer seguimiento)
const seguimiento = filas.filter(f => estado(f) === 'presupuesto enviado');

if (!sinResponder.length && !proximos.length && !seguimiento.length) return [];

let html = `<div style="font-family:Arial,sans-serif;color:#3b2a32"><h2 style="color:#e91e63;margin:0 0 12px">Buenos días, Katherine 🎈</h2>`;
if (sinResponder.length) html += `<h3>📩 Solicitudes sin responder (${sinResponder.length})</h3>${tabla(sinResponder)}`;
if (proximos.length) html += `<h3>📅 Eventos reservados en los próximos 7 días (${proximos.length})</h3>${tabla(proximos)}`;
if (seguimiento.length) html += `<h3>⏳ Presupuestos enviados pendientes de respuesta (${seguimiento.length})</h3>${tabla(seguimiento)}`;
html += `<p style="font-size:13px;color:#8a7680">Cambia la columna Estado en la hoja Pedidos para que este resumen se actualice.</p></div>`;

const partes = [];
if (sinResponder.length) partes.push(`${sinResponder.length} sin responder`);
if (proximos.length) partes.push(`${proximos.length} eventos esta semana`);
if (seguimiento.length) partes.push(`${seguimiento.length} por seguir`);
return [{ json: { asunto: `🎈 Resumen Ballonette: ${partes.join(' · ')}`, html } }];
